#include "elevsim.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <inttypes.h>
#include <stdarg.h>

#define R_HALL_UP 1u
#define R_HALL_DOWN 2u
#define R_DEST 4u
#define R_GROUP 8u
#define R_STAGE 16u
#define R_BYPASS_MARK 0x80000000u

static uint64_t qus(const Config*c,int ms){if(ms<=0)return 0;uint64_t tick=(uint64_t)c->tick_ms*1000;return es_ceil_div_u64((uint64_t)ms*1000,tick)*tick;}
static int hi(int floor,int dir){return (floor-1)*2+(dir>0?0:1);} static int hdir(int idx){return (idx%2)==0?1:-1;} static int hfloor(int idx){return idx/2+1;}
static int nonlobby_rank(const Config*c,int floor){if(floor==c->lobby)return -1;return floor<c->lobby?floor-1:floor-2;}
static int floor_from_nonlobby_rank(const Config*c,int rank){int f=rank+1;return f>=c->lobby?f+1:f;}
static int zone_owner_for_floor(const Config*c,int floor){int r=nonlobby_rank(c,floor);if(r<0)return -1;int non=c->floors-1,base=non/(int)c->car_n,rem=non%(int)c->car_n,off=0;for(size_t i=0;i<c->car_n;i++){int sz=base+((int)i<rem);if(r>=off&&r<off+sz)return(int)i;off+=sz;}return -1;}
static int zone_mid_floor(const Config*c,int ci){int non=c->floors-1,base=non/(int)c->car_n,rem=non%(int)c->car_n,off=0;for(int i=0;i<ci;i++)off+=base+(i<rem);int sz=base+(ci<rem);if(sz<=0)return 0;return floor_from_nonlobby_rank(c,off+(sz-1)/2);}
static const char*dstr(int d){return d>0?"UP":d<0?"DOWN":"IDLE";}
static const char*mstr(MotionState m){switch(m){case MOT_STOPPED:return"STOPPED";case MOT_ACCEL:return"ACCELERATING";case MOT_CRUISE:return"CRUISING";case MOT_DECEL:return"DECELERATING";case MOT_LEVEL:return"LEVELING";}return"STOPPED";}
static const char*doorstr(DoorState d){return d==DOOR_CLOSED?"CLOSED":d==DOOR_OPENING?"OPENING":d==DOOR_OPEN?"OPEN":"CLOSING";}
static const char *event_atom(char *dst,size_t cap,const char *src){bool quote=false;for(const unsigned char*p=(const unsigned char*)src;*p;p++)if(*p<=0x20||*p=='='||*p=='"'||*p=='\\'){quote=true;break;}if(!quote)return src;size_t n=0;if(cap<3)return"\"\"";dst[n++]='"';for(const unsigned char*p=(const unsigned char*)src;*p&&n+2<cap;p++){const char*esc=NULL;char ub[7];switch(*p){case '"':esc="\\\"";break;case '\\':esc="\\\\";break;case '\b':esc="\\b";break;case '\f':esc="\\f";break;case '\n':esc="\\n";break;case '\r':esc="\\r";break;case '\t':esc="\\t";break;default:break;}if(!esc&&*p<0x20){snprintf(ub,sizeof ub,"\\u%04x",(unsigned)*p);esc=ub;}if(esc){size_t k=strlen(esc);if(n+k+1>=cap)break;memcpy(dst+n,esc,k);n+=k;}else dst[n++]=(char)*p;}dst[n++]='"';dst[n]=0;return dst;}
static void ev(Simulation*s,const char*type,const char*fmt,...){if(!s->events)return;fprintf(s->events,"%" PRIu64 " %s",s->now_us,type);if(fmt&&*fmt){fputc(' ',s->events);va_list ap;va_start(ap,fmt);vfprintf(s->events,fmt,ap);va_end(ap);}fputc('\n',s->events);}
static bool simple_event_atom(const char*s){if(!s||!*s)return false;for(const unsigned char*p=(const unsigned char*)s;*p;p++)if(!((*p>='A'&&*p<='Z')||(*p>='a'&&*p<='z')||(*p>='0'&&*p<='9')||*p=='_'||*p=='-'||*p=='.'))return false;return true;}
static char *put_u64_dec(char*p,uint64_t v){char t[32];size_t n=0;do{t[n++]=(char)('0'+v%10);v/=10;}while(v);while(n)*p++=t[--n];return p;}static char*put_i_dec(char*p,int v){if(v<0){*p++='-';return put_u64_dec(p,(uint64_t)(-(int64_t)v));}return put_u64_dec(p,(uint64_t)v);}
static void ev_full_bypass(Simulation*s,uint32_t pid,const char*id,int floor){if(!s->events)return;if(!simple_event_atom(id)){char q[512];ev(s,"CAR_FULL_BYPASS","passenger_id=%" PRIu32 " car_id=%s floor=%d",pid,event_atom(q,sizeof q,id),floor);return;}char b[192],*p=b;p=put_u64_dec(p,s->now_us);const char*a=" CAR_FULL_BYPASS passenger_id=";memcpy(p,a,strlen(a));p+=strlen(a);p=put_u64_dec(p,pid);a=" car_id=";memcpy(p,a,strlen(a));p+=strlen(a);size_t n=strlen(id);memcpy(p,id,n);p+=n;a=" floor=";memcpy(p,a,strlen(a));p+=strlen(a);p=put_i_dec(p,floor);*p++='\n';if(fwrite(b,1,(size_t)(p-b),s->events)!=(size_t)(p-b)&&!s->err->code)es_error(s->err,7,0,"event output write failed");}

static bool wq_push(WaitQueue*q,uint32_t id,EsError*e){if(q->n==q->cap){size_t nc=q->cap?q->cap*2:16;uint32_t*p=es_realloc(q->ids,nc*sizeof*p,e);if(!p)return false;q->ids=p;q->cap=nc;}q->ids[q->n++]=id;return true;}
static bool wq_insert_id_sorted(WaitQueue*q,uint32_t id,EsError*e){if(q->n==q->cap){size_t nc=q->cap?q->cap*2:16;uint32_t*p=es_realloc(q->ids,nc*sizeof*p,e);if(!p)return false;q->ids=p;q->cap=nc;}size_t i=q->n;while(i>q->head&&q->ids[i-1]>id){q->ids[i]=q->ids[i-1];i--;}q->ids[i]=id;q->n++;return true;}
static void wq_advance(WaitQueue*q,const Trace*t){while(q->head<q->n&&t->p[q->ids[q->head]-1].state!=P_WAITING)q->head++;}
static WaitQueue*dc_commit_q(Simulation*s,int ci,int h){return&s->dc_commits[(size_t)ci*(size_t)(s->cfg->floors*2)+(size_t)h];}
static const WaitQueue*dc_commit_q_const(const Simulation*s,int ci,int h){return&s->dc_commits[(size_t)ci*(size_t)(s->cfg->floors*2)+(size_t)h];}
static bool car_vec_push(uint32_t**a,size_t*n,size_t*cap,uint32_t id,EsError*e){if(*n==*cap){size_t nc=*cap?*cap*2:8;uint32_t*q=es_realloc(*a,nc*sizeof*q,e);if(!q)return false;*a=q;*cap=nc;}(*a)[(*n)++]=id;return true;}
static void remove_u32(uint32_t*a,size_t*n,size_t i){memmove(a+i,a+i+1,(*n-i-1)*sizeof*a);(*n)--;}static void remove_u64(uint64_t*a,size_t*n,size_t i){memmove(a+i,a+i+1,(*n-i-1)*sizeof*a);(*n)--;}
static bool lane_push(CarState*c,bool board,uint32_t id,uint64_t done,EsError*e){uint32_t**a=board?&c->boarding:&c->alighting;uint64_t**d=board?&c->boarding_done:&c->alighting_done;size_t*n=board?&c->boarding_n:&c->alighting_n;size_t*cap=board?&c->boarding_cap:&c->alighting_cap;if(*n==*cap){size_t nc=*cap?*cap*2:8;uint32_t*qa=es_realloc(*a,nc*sizeof*qa,e);if(!qa)return false;uint64_t*qd=es_realloc(*d,nc*sizeof*qd,e);if(!qd){*a=qa;return false;}*a=qa;*d=qd;*cap=nc;}(*a)[*n]=id;(*d)[*n]=done;(*n)++;return true;}
static bool route_reserve(CarState*c,size_t need,EsError*e){if(need<=c->route_cap)return true;size_t nc=c->route_cap?c->route_cap*2:8;while(nc<need)nc*=2;Stop*q=es_realloc(c->route,nc*sizeof*q,e);if(!q)return false;c->route=q;c->route_cap=nc;return true;}
static unsigned reason_hall(int d){return d>0?R_HALL_UP:R_HALL_DOWN;}static int route_find(const CarState*c,int f){for(size_t i=0;i<c->route_n;i++)if(c->route[i].floor==f)return(int)i;return-1;}
static bool route_insert(CarState*c,size_t idx,Stop st,EsError*e){int ex=route_find(c,st.floor);if(ex>=0){c->route[ex].reasons|=st.reasons;if(c->route[ex].hall_dir&&st.hall_dir&&c->route[ex].hall_dir!=st.hall_dir)c->route[ex].hall_dir=0;else if(!c->route[ex].hall_dir)c->route[ex].hall_dir=st.hall_dir;return true;}if(idx>c->route_n)idx=c->route_n;if(!route_reserve(c,c->route_n+1,e))return false;memmove(c->route+idx+1,c->route+idx,(c->route_n-idx)*sizeof*c->route);c->route[idx]=st;c->route_n++;return true;}
static bool route_append(CarState*c,Stop st,EsError*e){return route_insert(c,c->route_n,st,e);}static void route_remove_reason(CarState*c,int floor,unsigned reason){for(size_t i=0;i<c->route_n;i++)if(c->route[i].floor==floor){c->route[i].reasons&=~reason;if(!c->route[i].reasons){memmove(c->route+i,c->route+i+1,(c->route_n-i-1)*sizeof*c->route);c->route_n--;}return;}}
static double route_added_distance(const Config*c,const CarState*car,int floor,size_t idx){if(route_find(car,floor)>=0)return 0;if(idx>car->route_n)idx=car->route_n;double start=car->moving?es_floor_pos(car->leg_target,c->floor_height):car->position,x=es_floor_pos(floor,c->floor_height),prev=idx?es_floor_pos(car->route[idx-1].floor,c->floor_height):start;if(idx==car->route_n)return fabs(x-prev);double next=es_floor_pos(car->route[idx].floor,c->floor_height);return fabs(x-prev)+fabs(next-x)-fabs(next-prev);}
static size_t best_distance_insert(const Config*c,const CarState*car,int floor){int ex=route_find(car,floor);if(ex>=0)return(size_t)ex;size_t first=0;if(!car->moving&&car->door!=DOOR_CLOSED&&car->route_n&&(car->route[0].reasons&R_DEST)&&car->onboard_n)first=1;double best=0;size_t bi=first;bool have=false;for(size_t i=first;i<=car->route_n;i++){double x=route_added_distance(c,car,floor,i);if(!have||(x<best&&!es_nearly_equal(x,best))){best=x;bi=i;have=true;}}return bi;}
static bool route_add_distance(Simulation*s,int ci,int floor,unsigned reason,int dir){return route_insert(&s->cars[ci],best_distance_insert(s->cfg,&s->cars[ci],floor),(Stop){floor,reason,dir,-1},s->err);}
static bool route_add_sweep(Simulation*s,int ci,int floor,unsigned reason,int dir){CarState*c=&s->cars[ci];int sd=c->service_dir;if(sd==DIR_IDLE)sd=c->moving?c->dir:(floor>c->floor?DIR_UP:floor<c->floor?DIR_DOWN:dir);size_t idx=c->route_n;if(dir==sd){idx=0;while(idx<c->route_n){int f=c->route[idx].floor;if((sd>0&&f>floor)||(sd<0&&f<floor))break;idx++;}}else{idx=c->route_n;if(sd>0){while(idx>0&&c->route[idx-1].floor<floor)idx--;}else{while(idx>0&&c->route[idx-1].floor>floor)idx--;}}return route_insert(c,idx,(Stop){floor,reason,dir,-1},s->err);}

static double leg_T(const ElevatorCfg*e,double D,double*a,double*b,double*d,double*v){return es_motion_profile(e->vmax,e->accel,e->decel,D,a,b,d,v);}static uint64_t travel_us(const Config*c,const ElevatorCfg*e,int from,int to){double D=fabs(es_floor_pos(to,c->floor_height)-es_floor_pos(from,c->floor_height)),a,b,d,v;double T=leg_T(e,D,&a,&b,&d,&v);uint64_t tick=(uint64_t)c->tick_ms*1000,raw=(uint64_t)ceil(T*1e6-1e-12);return es_ceil_div_u64(raw,tick)*tick;}
static uint64_t pred_travel_us(const Simulation*s,int ci,int from,int to){size_t f=(size_t)s->cfg->floors;return s->travel_table[((size_t)ci*f+(size_t)(from-1))*f+(size_t)(to-1)];}
typedef struct{bool feasible;double pickup_s,added_s,load_ratio;size_t added_stops;int added_reversals;}Pred;
static bool candidate_waiter(const Simulation*s,int h,int ci){const WaitQueue*q=&s->queues[h];for(size_t k=q->head;k<q->n;k++){const Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state==P_WAITING&&car_serves_od(&s->cfg->cars[ci],p->origin,p->dest))return true;}return false;}
static double reserved_ratio(const Simulation*s,int ci){return(double)s->cars[ci].reserved/s->cfg->cars[ci].capacity;}
static bool pred_waiter_eligible(const Simulation*s,int ci,const Passenger*p,int candidate_hidx,bool dc){if(p->state!=P_WAITING||!car_serves_od(&s->cfg->cars[ci],p->origin,p->dest))return false;if(dc)return p->car==ci&&p->group_id>=0;int h=hi(p->origin,p->dir);return h==candidate_hidx||(s->halls[h].active&&s->halls[h].owner==ci);}
static uint64_t pred_stop_service_us(const Simulation*s,int ci,int floor,uint32_t*occ,uint16_t*destc,int candidate_hidx,bool dc,bool*candidate_boardable,size_t required){
const ElevatorCfg*ec=&s->cfg->cars[ci];size_t alight=destc[floor];if(alight){destc[floor]=0;if(*occ>=(uint32_t)alight)*occ-=(uint32_t)alight;else *occ=0;}
size_t board=0,cand=0;for(int dp=0;candidate_hidx!=-2&&dp<2;dp++){int dir=dp==0?DIR_UP:DIR_DOWN,h=hi(floor,dir);if(!dc&&h!=candidate_hidx&&(!s->halls[h].active||s->halls[h].owner!=ci))continue;const WaitQueue*q=dc?dc_commit_q_const(s,ci,h):&s->queues[h];for(size_t k=q->head;k<q->n&&*occ<(uint32_t)ec->capacity;k++){const Passenger*p=&s->trace.p[q->ids[k]-1];if(dc){if(p->state!=P_WAITING||p->car!=ci||p->group_id<0)continue;}else if(!pred_waiter_eligible(s,ci,p,candidate_hidx,false))continue;(*occ)++;board++;if(h==candidate_hidx)cand++;destc[p->dest]++;}}
if(candidate_boardable&&cand>=required)*candidate_boardable=true;
uint64_t transfer=0;if(alight){uint64_t b=es_ceil_div_u64(alight,(uint64_t)ec->alight_lanes);transfer=qus(s->cfg,ec->alight_ms)*b;}if(board){uint64_t b=es_ceil_div_u64(board,(uint64_t)ec->board_lanes),x=qus(s->cfg,ec->board_ms)*b;if(x>transfer)transfer=x;}uint64_t dwell=qus(s->cfg,ec->dwell_ms);if(transfer>dwell)dwell=transfer;return qus(s->cfg,ec->door_open_ms)+dwell+qus(s->cfg,ec->door_close_ms);
}
static uint64_t pred_candidate_stop_us(const Simulation*s,int ci,int floor,uint32_t*occ,uint16_t*destc,int hidx,bool dc,const uint32_t*members,size_t mn,bool*ok,uint32_t*pre){const ElevatorCfg*ec=&s->cfg->cars[ci];if(!dc){uint32_t before=*occ;uint64_t u=pred_stop_service_us(s,ci,floor,occ,destc,hidx,false,ok,1);if(pre)*pre=before;return u;}uint64_t u=pred_stop_service_us(s,ci,floor,occ,destc,-1,true,NULL,0);if(pre)*pre=*occ;if((size_t)(ec->capacity-(int)*occ)>=mn){*ok=true;size_t board=0;for(size_t m=0;m<mn;m++){const Passenger*p=&s->trace.p[members[m]-1];(*occ)++;board++;destc[p->dest]++;}if(board){uint64_t b=es_ceil_div_u64(board,(uint64_t)ec->board_lanes),bt=qus(s->cfg,ec->board_ms)*b,dwell=qus(s->cfg,ec->dwell_ms);if(bt>dwell)u+=bt-dwell;}}return u;}
static uint64_t pred_initial_residual(const Simulation*s,int ci,int*pos){const CarState*c=&s->cars[ci];const ElevatorCfg*ec=&s->cfg->cars[ci];uint64_t t=0;*pos=c->floor;if(c->moving){t=c->leg_arrival_us>s->now_us?c->leg_arrival_us-s->now_us:0;*pos=c->leg_target;return t;}if(c->door==DOOR_OPENING){t=c->timer_end_us>s->now_us?c->timer_end_us-s->now_us:0;t+=qus(s->cfg,ec->dwell_ms)+qus(s->cfg,ec->door_close_ms);}else if(c->door==DOOR_OPEN){uint64_t de=c->open_since_us+qus(s->cfg,ec->dwell_ms);if(de>s->now_us)t=de-s->now_us;t+=qus(s->cfg,ec->door_close_ms);}else if(c->door==DOOR_CLOSING)t=c->timer_end_us>s->now_us?c->timer_end_us-s->now_us:0;return t;}
static uint64_t pred_baseline_finish(const Simulation*s,int ci){const CarState*c=&s->cars[ci];int pos;uint64_t t=pred_initial_residual(s,ci,&pos);uint32_t occ=c->reserved;uint16_t destc[ES_MAX_FLOORS+1]={0};for(size_t i=0;i<c->onboard_n;i++)destc[s->trace.p[c->onboard[i]-1].dest]++;for(size_t i=0;i<c->boarding_n;i++)destc[s->trace.p[c->boarding[i]-1].dest]++;if(c->moving&&c->has_current_stop)t+=pred_stop_service_us(s,ci,pos,&occ,destc,-1,s->alg==6,NULL,0);for(size_t i=0;i<c->route_n;i++){int f=c->route[i].floor;t+=pred_travel_us(s,ci,pos,f);pos=f;int ph=(s->alg==6&&!(c->route[i].reasons&R_GROUP))?-2:-1;t+=pred_stop_service_us(s,ci,f,&occ,destc,ph,s->alg==6,NULL,0);}return t;}
static Pred predictor_pickup_with_base(const Simulation*s,int ci,int hidx,size_t ins,const uint32_t*members,size_t mn,uint64_t base){Pred r={0};const CarState*c=&s->cars[ci];const ElevatorCfg*ec=&s->cfg->cars[ci];int floor=hfloor(hidx);bool dc=mn>0;if(dc){for(size_t m=0;m<mn;m++){const Passenger*p=&s->trace.p[members[m]-1];if(!car_serves_od(ec,p->origin,p->dest))return r;}}else if(!candidate_waiter(s,hidx,ci))return r;int existing=route_find(c,floor);if(existing>=0)ins=(size_t)existing;if(ins>c->route_n)ins=c->route_n;uint32_t occ=c->reserved;uint16_t destc[ES_MAX_FLOORS+1]={0};for(size_t i=0;i<c->onboard_n;i++)destc[s->trace.p[c->onboard[i]-1].dest]++;for(size_t i=0;i<c->boarding_n;i++)destc[s->trace.p[c->boarding[i]-1].dest]++;int pos;uint64_t t=pred_initial_residual(s,ci,&pos);bool picked=false;
if(!c->moving&&c->door==DOOR_OPEN&&c->floor==floor){bool cb=false;uint32_t pre=occ;(void)pred_candidate_stop_us(s,ci,floor,&occ,destc,hidx,dc,members,mn,&cb,&pre);r.load_ratio=(double)pre/ec->capacity;r.feasible=cb;if(cb){r.pickup_s=0;picked=true;}}
if(c->moving&&c->has_current_stop){bool cb=false;uint64_t open_at=t+qus(s->cfg,ec->door_open_ms);if(pos==floor){uint32_t pre=occ;t+=pred_candidate_stop_us(s,ci,pos,&occ,destc,hidx,dc,members,mn,&cb,&pre);if(!picked){r.feasible=cb;r.pickup_s=open_at/1e6;r.load_ratio=(double)pre/ec->capacity;picked=true;}}else t+=pred_stop_service_us(s,ci,pos,&occ,destc,-1,dc,NULL,0);}
for(size_t step=0;step<=c->route_n;step++){bool insert_here=existing<0&&step==ins;if(insert_here){t+=pred_travel_us(s,ci,pos,floor);pos=floor;bool cb=false;uint64_t open_at=t+qus(s->cfg,ec->door_open_ms);uint32_t pre=occ;t+=pred_candidate_stop_us(s,ci,floor,&occ,destc,hidx,dc,members,mn,&cb,&pre);if(!picked){r.feasible=cb;r.pickup_s=open_at/1e6;r.load_ratio=(double)pre/ec->capacity;picked=true;}}if(step<c->route_n){int f=c->route[step].floor;t+=pred_travel_us(s,ci,pos,f);pos=f;bool cb=false;uint64_t open_at=t+qus(s->cfg,ec->door_open_ms);if(f==floor){uint32_t pre=occ;t+=pred_candidate_stop_us(s,ci,f,&occ,destc,hidx,dc,members,mn,&cb,&pre);if(!picked){r.feasible=cb;r.pickup_s=open_at/1e6;r.load_ratio=(double)pre/ec->capacity;picked=true;}}else{int ph=(dc&&!(c->route[step].reasons&R_GROUP))?-2:-1;t+=pred_stop_service_us(s,ci,f,&occ,destc,ph,dc,NULL,0);}}}
r.added_s=t>=base?(t-base)/1e6:0;r.added_stops=existing>=0?0:1;int startdir=c->moving?c->dir:c->last_nonidle;int firstdir=0;double start=c->moving?es_floor_pos(c->leg_target,s->cfg->floor_height):c->position;double fp=es_floor_pos(floor,s->cfg->floor_height);if(fp>start)firstdir=1;else if(fp<start)firstdir=-1;r.added_reversals=(startdir&&firstdir&&startdir!=firstdir)?1:0;return r;}
static Pred predictor_pickup(const Simulation*s,int ci,int hidx,size_t ins,const uint32_t*members,size_t mn){return predictor_pickup_with_base(s,ci,hidx,ins,members,mn,pred_baseline_finish(s,ci));}

typedef struct{uint64_t t;int pos;uint32_t occ;uint16_t destc[ES_MAX_FLOORS+1];}PredState;
static bool dc_prefix_states(Simulation*s,int ci,PredState**out){
 if(s->dc_prefix_valid[ci]&&s->dc_prefix_cache[ci]){*out=(PredState*)s->dc_prefix_cache[ci];return true;}
 const CarState*c=&s->cars[ci];size_t n=c->route_n+1;PredState*pf=es_calloc(n,sizeof*pf,s->err);if(!pf)return false;
 PredState st={0};st.occ=c->reserved;for(size_t i=0;i<c->onboard_n;i++)st.destc[s->trace.p[c->onboard[i]-1].dest]++;for(size_t i=0;i<c->boarding_n;i++)st.destc[s->trace.p[c->boarding[i]-1].dest]++;
 st.t=pred_initial_residual(s,ci,&st.pos);if(c->moving&&c->has_current_stop)st.t+=pred_stop_service_us(s,ci,st.pos,&st.occ,st.destc,-1,true,NULL,0);pf[0]=st;
 for(size_t i=0;i<c->route_n;i++){st=pf[i];int f=c->route[i].floor;st.t+=pred_travel_us(s,ci,st.pos,f);st.pos=f;int ph=(c->route[i].reasons&R_GROUP)?-1:-2;st.t+=pred_stop_service_us(s,ci,f,&st.occ,st.destc,ph,true,NULL,0);pf[i+1]=st;}
 s->dc_prefix_cache[ci]=pf;s->dc_prefix_valid[ci]=true;*out=pf;return true;
}
static void dc_prefix_invalidate(Simulation*s,int ci){if(ci<0||ci>=ES_MAX_CARS)return;free(s->dc_prefix_cache[ci]);s->dc_prefix_cache[ci]=NULL;s->dc_prefix_valid[ci]=false;}
static void dc_prefix_reset_all(Simulation*s){for(size_t ci=0;ci<s->cfg->car_n;ci++)dc_prefix_invalidate(s,(int)ci);}
static Pred dc_predict_from_prefix(const Simulation*s,int ci,int hidx,size_t ins,const uint32_t*members,size_t mn,const PredState*pf){
 Pred r={0};const CarState*c=&s->cars[ci];const ElevatorCfg*ec=&s->cfg->cars[ci];int floor=hfloor(hidx);PredState st=pf[ins];
 st.t+=pred_travel_us(s,ci,st.pos,floor);st.pos=floor;uint64_t open_at=st.t+qus(s->cfg,ec->door_open_ms);bool cb=false;uint32_t pre=st.occ;st.t+=pred_candidate_stop_us(s,ci,floor,&st.occ,st.destc,hidx,true,members,mn,&cb,&pre);r.feasible=cb;r.pickup_s=open_at/1e6;r.load_ratio=(double)pre/ec->capacity;if(!cb)return r;
 for(size_t step=ins;step<c->route_n;step++){int f=c->route[step].floor;st.t+=pred_travel_us(s,ci,st.pos,f);st.pos=f;int ph=(c->route[step].reasons&R_GROUP)?-1:-2;st.t+=pred_stop_service_us(s,ci,f,&st.occ,st.destc,ph,true,NULL,0);}
 uint64_t base=pf[c->route_n].t;r.added_s=st.t>=base?(st.t-base)/1e6:0;r.added_stops=1;int startdir=c->moving?c->dir:c->last_nonidle;int firstdir=0;double start=c->moving?es_floor_pos(c->leg_target,s->cfg->floor_height):c->position,fp=es_floor_pos(floor,s->cfg->floor_height);if(fp>start)firstdir=1;else if(fp<start)firstdir=-1;r.added_reversals=(startdir&&firstdir&&startdir!=firstdir)?1:0;return r;
}
static int owned_halls(const Simulation*s,int ci){int n=0;for(int h=0;h<s->cfg->floors*2;h++)if(s->halls[h].active&&s->halls[h].owner==ci)n++;return n;}
static double sweep_distance_to(const Simulation*s,int ci,int floor,int reqdir){const CarState*c=&s->cars[ci];double cur=c->moving?es_floor_pos(c->leg_target,s->cfg->floor_height):c->position,total=0;int sd=c->service_dir;if(sd==DIR_IDLE)sd=c->moving?c->dir:reqdir;double target=es_floor_pos(floor,s->cfg->floor_height);if(sd==reqdir&&((sd>0&&target>=cur)||(sd<0&&target<=cur))){double prev=cur;for(size_t i=0;i<c->route_n;i++){double x=es_floor_pos(c->route[i].floor,s->cfg->floor_height);if((sd>0&&x<prev)||(sd<0&&x>prev))continue;total+=fabs(x-prev);prev=x;if(c->route[i].floor==floor)return total;}return total+fabs(target-prev);}double prev=cur,ext=cur;for(size_t i=0;i<c->route_n;i++){double x=es_floor_pos(c->route[i].floor,s->cfg->floor_height);if((sd>0&&x>ext)||(sd<0&&x<ext))ext=x;}total+=fabs(ext-prev)+fabs(target-ext);return total;}
static int choose_nearest(const Simulation*s,int h){int floor=hfloor(h),dir=hdir(h),best=-1;double bs=HUGE_VAL;for(size_t i=0;i<s->cfg->car_n;i++){int ci=(int)i;if(!candidate_waiter(s,h,ci))continue;const CarState*c=&s->cars[ci];double sc=fabs(c->position-es_floor_pos(floor,s->cfg->floor_height));if(c->moving){double req=es_floor_pos(floor,s->cfg->floor_height);bool toward=(c->dir>0&&req>=c->position)||(c->dir<0&&req<=c->position);if(!toward)sc+=s->cfg->alg.away_penalty;else if(dir!=c->dir)sc+=s->cfg->alg.opposite_penalty;}bool take=best<0||(sc<bs&&!es_nearly_equal(sc,bs));if(!take&&es_nearly_equal(sc,bs)){double lr=reserved_ratio(s,ci),br=reserved_ratio(s,best);if(lr<br&&!es_nearly_equal(lr,br))take=true;else if(es_nearly_equal(lr,br)&&(c->route_n<s->cars[best].route_n||(c->route_n==s->cars[best].route_n&&ci<best)))take=true;}if(take){best=ci;bs=sc;}}return best;}
static int choose_collective(const Simulation*s,int h){int floor=hfloor(h),dir=hdir(h),best=-1,bclass=99;double bd=HUGE_VAL;for(size_t i=0;i<s->cfg->car_n;i++){int ci=(int)i;if(!candidate_waiter(s,h,ci))continue;const CarState*c=&s->cars[ci];int cl;bool sweep=c->moving||c->service_dir!=DIR_IDLE;if(sweep&&c->service_dir==dir&&((dir>0&&c->floor<=floor)||(dir<0&&c->floor>=floor)))cl=1;else if(!c->moving&&c->route_n==0&&c->door==DOOR_CLOSED)cl=2;else cl=3;double d=sweep_distance_to(s,ci,floor,dir);bool take=best<0||cl<bclass||(cl==bclass&&d<bd&&!es_nearly_equal(d,bd));if(!take&&cl==bclass&&es_nearly_equal(d,bd)){double lr=reserved_ratio(s,ci),br=reserved_ratio(s,best);if((lr<br&&!es_nearly_equal(lr,br))||(es_nearly_equal(lr,br)&&ci<best))take=true;}if(take){best=ci;bclass=cl;bd=d;}}return best;}
static int choose_scan(const Simulation*s,int h){int floor=hfloor(h),dir=hdir(h),best=-1;double bd=HUGE_VAL;for(size_t i=0;i<s->cfg->car_n;i++){int ci=(int)i;if(!candidate_waiter(s,h,ci))continue;const CarState*c=&s->cars[ci];double d=route_added_distance(s->cfg,c,floor,best_distance_insert(s->cfg,c,floor));bool take=best<0||(d<bd&&!es_nearly_equal(d,bd));if(!take&&es_nearly_equal(d,bd)){int oh=owned_halls(s,ci),bh=owned_halls(s,best);if(oh<bh)take=true;else if(oh==bh){double lr=reserved_ratio(s,ci),br=reserved_ratio(s,best);if((lr<br&&!es_nearly_equal(lr,br))||(es_nearly_equal(lr,br)&&ci<best))take=true;}}if(take){best=ci;bd=d;}}(void)dir;return best;}
static bool eta_best_for_car(Simulation*s,int ci,int hidx,const uint32_t*members,size_t mn,bool forced,size_t*best_ins,Pred*best_pred,double*best_score){const CarState*c=&s->cars[ci];int floor=hfloor(hidx),ex=route_find(c,floor);size_t lo=0,hi2=forced?0:c->route_n;if(ex>=0)lo=hi2=(size_t)ex;bool use_prefix=mn&&s->alg==6&&ex<0&&!(c->door==DOOR_OPEN&&c->floor==floor)&&!(c->moving&&c->has_current_stop&&c->leg_target==floor);PredState*pf=NULL;uint64_t base=0;if(use_prefix){if(!dc_prefix_states(s,ci,&pf))return false;base=pf[c->route_n].t;}else if(mn&&s->alg==6){if(!s->dc_base_valid[ci]){s->dc_base_cache[ci]=pred_baseline_finish(s,ci);s->dc_base_valid[ci]=true;}base=s->dc_base_cache[ci];}else base=pred_baseline_finish(s,ci);bool have=false;double bs=HUGE_VAL;Pred bp={0};size_t bi=lo;for(size_t ins=lo;ins<=hi2;ins++){Pred pr=use_prefix?dc_predict_from_prefix(s,ci,hidx,ins,members,mn,pf):predictor_pickup_with_base(s,ci,hidx,ins,members,mn,base);if(!pr.feasible)continue;double age=(s->now_us-s->halls[hidx].active_since_us)/1e6,sc;if(mn){int unique=0;for(size_t m=0;m<mn;m++){int d=s->trace.p[members[m]-1].dest;bool seen=false;for(size_t x=0;x<m;x++)if(s->trace.p[members[x]-1].dest==d)seen=true;if(!seen&&route_find(c,d)<0)unique++;}sc=s->cfg->alg.dc_pickup*pr.pickup_s+s->cfg->alg.dc_route*pr.added_s+s->cfg->alg.dc_stops*unique+s->cfg->alg.dc_load*pr.load_ratio-s->cfg->alg.dc_age*age;}else sc=s->cfg->alg.ew_wait*pr.pickup_s+s->cfg->alg.ew_detour*pr.added_s+s->cfg->alg.ew_stops*pr.added_stops+s->cfg->alg.ew_load*pr.load_ratio+s->cfg->alg.ew_reverse*pr.added_reversals-s->cfg->alg.ew_fairness*age;bool take=!have||(sc<bs&&!es_nearly_equal(sc,bs));if(!take&&es_nearly_equal(sc,bs)){if(pr.pickup_s<bp.pickup_s&&!es_nearly_equal(pr.pickup_s,bp.pickup_s))take=true;else if(es_nearly_equal(pr.pickup_s,bp.pickup_s)&&pr.added_s<bp.added_s&&!es_nearly_equal(pr.added_s,bp.added_s))take=true;else if(es_nearly_equal(pr.pickup_s,bp.pickup_s)&&es_nearly_equal(pr.added_s,bp.added_s)&&ins<bi)take=true;}if(take){have=true;bs=sc;bp=pr;bi=ins;}}if(have){if(best_ins)*best_ins=bi;if(best_pred)*best_pred=bp;if(best_score)*best_score=bs;}return have;}
static int choose_eta(Simulation*s,int h,bool zoned){int floor=hfloor(h),best=-1;double bscore=HUGE_VAL;Pred bpred={0};int zone=zone_owner_for_floor(s->cfg,floor);bool primary=zoned&&floor!=s->cfg->lobby&&(s->now_us-s->halls[h].active_since_us<(uint64_t)s->cfg->alg.zone_overflow_s*1000000ULL);size_t di;Pred dp;double ds;if(primary&&(zone<0||!eta_best_for_car(s,zone,h,NULL,0,false,&di,&dp,&ds)))primary=false;for(size_t i=0;i<s->cfg->car_n;i++){int ci=(int)i;if(primary&&ci!=zone)continue;if(!candidate_waiter(s,h,ci))continue;size_t ins;Pred pr;double sc;if(!eta_best_for_car(s,ci,h,NULL,0,false,&ins,&pr,&sc))continue;bool take=best<0||(sc<bscore&&!es_nearly_equal(sc,bscore));if(!take&&es_nearly_equal(sc,bscore)){if(pr.pickup_s<bpred.pickup_s&&!es_nearly_equal(pr.pickup_s,bpred.pickup_s))take=true;else if(es_nearly_equal(pr.pickup_s,bpred.pickup_s)){if(pr.added_s<bpred.added_s&&!es_nearly_equal(pr.added_s,bpred.added_s))take=true;else if(es_nearly_equal(pr.added_s,bpred.added_s)){double lr=reserved_ratio(s,ci),br=reserved_ratio(s,best);if((lr<br&&!es_nearly_equal(lr,br))||(es_nearly_equal(lr,br)&&ci<best))take=true;}}}if(take){best=ci;bscore=sc;bpred=pr;}}return best;}
static int choose_urgent(const Simulation*s,int h){int best=-1;double bp=HUGE_VAL;for(size_t ci=0;ci<s->cfg->car_n;ci++){if(!candidate_waiter(s,h,(int)ci))continue;Pred pr=predictor_pickup(s,(int)ci,h,0,NULL,0);if(!pr.feasible)continue;if(best<0||(pr.pickup_s<bp&&!es_nearly_equal(pr.pickup_s,bp))||(es_nearly_equal(pr.pickup_s,bp)&&(int)ci<best)){best=(int)ci;bp=pr.pickup_s;}}return best;}
static bool hall_assign(Simulation*s,int h,int car,bool re){Hall*x=&s->halls[h];int old=re?x->previous_owner:x->owner;x->owner=car;int floor=hfloor(h),dir=hdir(h);if(re&&old>=0){char a[512],b[512];ev(s,"CALL_REASSIGN","kind=hall old_car_id=%s new_car_id=%s floor=%d direction=%s",event_atom(a,sizeof a,s->cfg->cars[old].id),event_atom(b,sizeof b,s->cfg->cars[car].id),floor,dstr(dir));}else{char a[512];ev(s,"CALL_ASSIGN","kind=hall car_id=%s floor=%d direction=%s",event_atom(a,sizeof a,s->cfg->cars[car].id),floor,dstr(dir));}x->previous_owner=-1;if(s->alg==1||s->alg==2)return route_add_sweep(s,car,floor,reason_hall(dir),dir);if(s->alg==3||s->alg==5){size_t ins;Pred pr;double sc;if(eta_best_for_car(s,car,h,NULL,0,x->urgent,&ins,&pr,&sc))return route_insert(&s->cars[car],ins,(Stop){floor,reason_hall(dir),dir,-1},s->err);}return route_add_distance(s,car,floor,reason_hall(dir),dir);}
static bool any_work_ahead(const Simulation*s,int ci,int dir,int floor){const CarState*c=&s->cars[ci];for(size_t i=0;i<c->route_n;i++)if((dir>0&&c->route[i].floor>floor)||(dir<0&&c->route[i].floor<floor))return true;for(size_t i=0;i<c->onboard_n;i++){const Passenger*p=&s->trace.p[c->onboard[i]-1];if((dir>0&&p->dest>floor)||(dir<0&&p->dest<floor))return true;}return false;}
static bool policy_board_ok(const Simulation*s,int ci,const Passenger*p){if(s->alg==6)return p->car==ci&&p->group_id>=0;int h=hi(p->origin,p->dir);if(s->halls[h].owner!=ci)return false;if(s->alg==1||s->alg==2){const CarState*c=&s->cars[ci];int sd=c->service_dir;if(sd!=DIR_IDLE&&p->dir!=sd&&any_work_ahead(s,ci,sd,p->origin))return false;}return true;}
static void hall_refresh(Simulation*s){for(int i=0;i<s->cfg->floors*2;i++){WaitQueue*q=&s->queues[i];wq_advance(q,&s->trace);bool active=q->head<q->n;Hall*h=&s->halls[i];if(active&&!h->active){h->active=true;h->owner=-1;h->previous_owner=-1;h->active_since_us=s->trace.p[q->ids[q->head]-1].arrival_us;h->oldest_id=q->ids[q->head];h->urgent=false;h->urgent_logged=false;h->overflow_considered=false;ev(s,"HALL_CALL_ACTIVE","floor=%d direction=%s oldest_passenger_id=%" PRIu32,hfloor(i),dstr(hdir(i)),h->oldest_id);}else if(!active&&h->active){h->active=false;h->owner=-1;h->urgent=false;ev(s,"HALL_CALL_CLEAR","floor=%d direction=%s",hfloor(i),dstr(hdir(i)));}else if(active){h->oldest_id=q->ids[q->head];uint64_t age=s->now_us-s->trace.p[h->oldest_id-1].arrival_us;if(age>s->max_hall_age_us)s->max_hall_age_us=age;}}}
static bool urgent_before(const Simulation*s,int ah,int bh){const Hall*a=&s->halls[ah],*b=&s->halls[bh];if(!b->urgent)return true;uint64_t aa=s->trace.p[a->oldest_id-1].arrival_us,ba=s->trace.p[b->oldest_id-1].arrival_us;if(aa!=ba)return aa<ba;return a->oldest_id<b->oldest_id;}
static void promote_urgent_ranked(Simulation*s,int ci,int h){CarState*c=&s->cars[ci];int ex=route_find(c,hfloor(h));if(ex<0)return;Stop st=c->route[ex];size_t dst=0;for(size_t i=0;i<c->route_n;i++){if((int)i==ex)continue;int oh=-1;if(c->route[i].reasons&R_HALL_UP)oh=hi(c->route[i].floor,DIR_UP);else if(c->route[i].reasons&R_HALL_DOWN)oh=hi(c->route[i].floor,DIR_DOWN);if(oh>=0&&s->halls[oh].active&&s->halls[oh].urgent&&s->halls[oh].owner==ci&&urgent_before(s,oh,h))dst++;else break;}if((size_t)ex==dst)return;if((size_t)ex>dst){memmove(c->route+dst+1,c->route+dst,((size_t)ex-dst)*sizeof*c->route);c->route[dst]=st;}else{memmove(c->route+ex,c->route+ex+1,(dst-(size_t)ex)*sizeof*c->route);c->route[dst]=st;}}
static bool conventional_dispatch(Simulation*s){for(int i=0;i<s->cfg->floors*2;i++){Hall*h=&s->halls[i];if(!h->active)continue;if(h->owner>=0&&!candidate_waiter(s,i,h->owner)){route_remove_reason(&s->cars[h->owner],hfloor(i),reason_hall(hdir(i)));h->previous_owner=h->owner;h->owner=-1;}uint64_t age=s->now_us-s->trace.p[h->oldest_id-1].arrival_us;if(age>=(uint64_t)s->cfg->starvation_s*1000000ULL&&!h->urgent){h->urgent=true;if(!h->urgent_logged){ev(s,"STARVATION_URGENT","floor=%d direction=%s oldest_passenger_id=%" PRIu32,hfloor(i),dstr(hdir(i)),h->oldest_id);h->urgent_logged=true;s->starvation_triggers++;}if(h->owner>=0){CarState*c=&s->cars[h->owner];if(!(c->moving&&c->leg_target==hfloor(i))){route_remove_reason(c,hfloor(i),reason_hall(hdir(i)));h->previous_owner=h->owner;h->owner=-1;}}}if(s->alg==4&&h->owner>=0&&!h->overflow_considered&&age>=(uint64_t)s->cfg->alg.zone_overflow_s*1000000ULL){h->overflow_considered=true;int nc=choose_eta(s,i,false);if(nc>=0&&nc!=h->owner){int old=h->owner;route_remove_reason(&s->cars[old],hfloor(i),reason_hall(hdir(i)));h->previous_owner=old;h->owner=-1;if(!hall_assign(s,i,nc,true))return false;continue;}}if(h->owner<0){int car=h->urgent?choose_urgent(s,i):(s->alg==0?choose_nearest(s,i):s->alg==1?choose_collective(s,i):s->alg==2?choose_scan(s,i):s->alg==4?choose_eta(s,i,true):choose_eta(s,i,false));if(car>=0){bool re=h->previous_owner>=0;if(!hall_assign(s,i,car,re))return false;if(h->urgent)promote_urgent_ranked(s,car,i);}}}return true;}
static size_t lower_arrival(const Trace*t,uint64_t x,bool strict){size_t l=0,r=t->n;while(l<r){size_t m=l+(r-l)/2,a=t->p[m].arrival_us;if(a<x||(!strict&&a==x))l=m+1;else r=m;}return l;}
static void adaptive_update(Simulation*s){if(s->alg!=5)return;uint64_t W=(uint64_t)s->cfg->alg.adaptive_window_s*1000000ULL;if(s->now_us<W)return;size_t lo=lower_arrival(&s->trace,s->now_us-W,false),upb=lower_arrival(&s->trace,s->now_us,false),up=0,down=0,inter=0;for(size_t i=lo;i<upb;i++){Passenger*p=&s->trace.p[i];if(p->origin==s->cfg->lobby)up++;else if(p->dest==s->cfg->lobby)down++;else inter++;}size_t n=up+down+inter;int cand=0;if(n){double rate=n*60.0/s->cfg->alg.adaptive_window_s;if(rate>=s->cfg->alg.adaptive_min_rate){if((double)up/n>=s->cfg->alg.adaptive_up)cand=1;else if((double)down/n>=s->cfg->alg.adaptive_down)cand=2;else if((double)inter/n>=s->cfg->alg.adaptive_inter)cand=3;}}if(cand!=s->adaptive_mode&&s->now_us-s->adaptive_since_us>=(uint64_t)s->cfg->alg.adaptive_hold_s*1000000ULL){static const char*M[]={"BALANCED","UP_PEAK","DOWN_PEAK","INTERFLOOR"};ev(s,"ADAPTIVE_MODE","old_mode=%s new_mode=%s",M[s->adaptive_mode],M[cand]);s->adaptive_mode=cand;s->adaptive_since_us=s->now_us;}}
static void adaptive_stage(Simulation*s){if(s->alg!=5||s->adaptive_mode==0)return;int reserve=(int)ceil(s->cfg->alg.adaptive_lobby_reserve*s->cfg->car_n);for(size_t i=0;i<s->cfg->car_n;i++){CarState*c=&s->cars[i];if(c->moving||c->route_n||c->door!=DOOR_CLOSED)continue;int target=0;if(s->adaptive_mode==1){if((int)i>=reserve)continue;if(s->cfg->lobby>=s->cfg->cars[i].service_min&&s->cfg->lobby<=s->cfg->cars[i].service_max)target=s->cfg->lobby;}else{int mid=zone_mid_floor(s->cfg,(int)i);if(mid){int lo=s->cfg->cars[i].service_min,h=s->cfg->cars[i].service_max;if(mid<lo)mid=lo;if(mid>h)mid=h;if(mid==s->cfg->lobby){int a=mid-1,b=mid+1;if(a>=lo)mid=a;else if(b<=h)mid=b;else mid=0;}target=mid;}}if(target&&target!=c->floor)(void)route_append(c,(Stop){target,R_STAGE,0,-1},s->err);}}
static uint32_t dc_group_mask(const Simulation*s,const uint32_t*m,size_t mn){if(!mn||mn>ES_MAX_CAPACITY)return 0;uint32_t mask=s->dc_capacity_mask[mn];for(size_t i=0;i<mn&&mask;i++)mask&=s->dc_service_mask[m[i]-1];return mask;}
static void dc_unassigned_append(Simulation*s,int h,uint32_t id){uint32_t tail=s->dc_htail[h];s->dc_prev[id]=tail;s->dc_next[id]=0;if(tail)s->dc_next[tail]=id;else s->dc_hhead[h]=id;s->dc_htail[h]=id;if(s->dc_hall_membership_version)s->dc_hall_membership_version[h]++;}
static void dc_unassigned_remove(Simulation*s,int h,uint32_t id){uint32_t prev=s->dc_prev[id],next=s->dc_next[id];if(prev)s->dc_next[prev]=next;else if(s->dc_hhead[h]==id)s->dc_hhead[h]=next;if(next)s->dc_prev[next]=prev;else if(s->dc_htail[h]==id)s->dc_htail[h]=prev;s->dc_prev[id]=0;/* keep dc_next[id] as an iteration breadcrumb after removal */if(s->dc_hall_membership_version)s->dc_hall_membership_version[h]++;}
static size_t dc_bucket_lower_bound(const Simulation*s,size_t key,uint32_t id){
 size_t l=s->dc_bucket_offsets[key],r=s->dc_bucket_offsets[key+1];
 while(l<r){size_t m=l+(r-l)/2;if(s->dc_bucket_ids[m]<=id)l=m+1;else r=m;}return l;
}
static size_t dc_build_group_linked(const Simulation*s,uint32_t seed_id,uint32_t*m){
 const Passenger*seed=&s->trace.p[seed_id-1];size_t n=1;m[0]=seed_id;
 uint32_t mask=s->dc_service_mask[seed_id-1]&s->dc_capacity_mask[1];
 int lo=seed->dest-s->cfg->alg.dc_span,hi2=seed->dest+s->cfg->alg.dc_span;if(lo<1)lo=1;if(hi2>s->cfg->floors)hi2=s->cfg->floors;
 size_t pos[ES_MAX_FLOORS],endp[ES_MAX_FLOORS];int dn=0,h=hi(seed->origin,seed->dir);
 for(int d=lo;d<=hi2;d++){size_t key=(size_t)h*(size_t)s->cfg->floors+(size_t)(d-1);pos[dn]=dc_bucket_lower_bound(s,key,seed_id);endp[dn]=s->dc_bucket_offsets[key+1];dn++;}
 while(n<(size_t)s->cfg->alg.dc_max_group){uint32_t best=UINT32_MAX;int bi=-1;for(int j=0;j<dn;j++){while(pos[j]<endp[j]){uint32_t id=s->dc_bucket_ids[pos[j]];const Passenger*p=&s->trace.p[id-1];if(p->state==P_NOT_ARRIVED){break;}if(p->state!=P_WAITING||p->car>=0||(s->dc_seen&&s->dc_seen[id-1]==s->dc_dispatch_epoch)){pos[j]++;continue;}if(id<best){best=id;bi=j;}break;}}if(bi<0)break;pos[bi]++;const Passenger*p=&s->trace.p[best-1];uint32_t nm=mask&s->dc_service_mask[p->id-1]&s->dc_capacity_mask[n+1];if(nm){m[n++]=p->id;mask=nm;}}
 return n;
}

static size_t dc_extend_cached_group(const Simulation*s,uint32_t seed_id,const DcInfeasibleCache*cc,uint32_t old_tail,uint32_t*m,bool*ok){
 (void)cc;(void)old_tail;*ok=false;return dc_build_group_linked(s,seed_id,m);
}


static void dc_mark_group(Simulation*s,const uint32_t*m,size_t n){if(s->dc_seen)for(size_t i=0;i<n;i++)s->dc_seen[m[i]-1]=s->dc_dispatch_epoch;}
static bool dc_urgent_floor_key(const Simulation*s,int ci,int floor,uint64_t*arr,uint32_t*pid){bool have=false;uint64_t ba=UINT64_MAX;uint32_t bp=UINT32_MAX;for(int dp=0;dp<2;dp++){int h=hi(floor,dp==0?DIR_UP:DIR_DOWN);const WaitQueue*q=dc_commit_q_const(s,ci,h);/* Commit queues are sorted by canonical passenger id. Canonical ids are assigned in nondecreasing arrival order, so the first still-waiting committed passenger is the oldest candidate in this direction. */for(size_t k=q->head;k<q->n;k++){const Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state!=P_WAITING||p->car!=ci||p->group_id<0)continue;if(s->now_us-p->arrival_us<(uint64_t)s->cfg->starvation_s*1000000ULL)break;if(!have||p->arrival_us<ba||(p->arrival_us==ba&&p->id<bp)){have=true;ba=p->arrival_us;bp=p->id;}break;}}if(have){if(arr)*arr=ba;if(pid)*pid=bp;}return have;}
static bool dc_reorder_urgent_car(Simulation*s,int ci){
 CarState*c=&s->cars[ci];size_t n=c->route_n;if(n<2){s->dc_urgent_applied_route_version[ci]=s->dc_route_version[ci];return true;}
 typedef struct {Stop st;bool urgent;uint64_t arrival;uint32_t pid;size_t original;} UrgentStop;
 UrgentStop a[ES_MAX_FLOORS];if(n>ES_MAX_FLOORS){es_error(s->err,6,0,"route exceeds floor bound");return false;}
 for(size_t i=0;i<n;i++){a[i].st=c->route[i];a[i].original=i;a[i].arrival=UINT64_MAX;a[i].pid=UINT32_MAX;a[i].urgent=dc_urgent_floor_key(s,ci,c->route[i].floor,&a[i].arrival,&a[i].pid);}
 for(size_t i=1;i<n;i++){UrgentStop x=a[i];size_t j=i;while(j){UrgentStop*y=&a[j-1];bool before=false;if(x.urgent!=y->urgent)before=x.urgent&&!y->urgent;else if(x.urgent){before=x.arrival<y->arrival||(x.arrival==y->arrival&&(x.pid<y->pid||(x.pid==y->pid&&x.original<y->original)));}else before=x.original<y->original;if(!before)break;a[j]=a[j-1];j--;}a[j]=x;}
 bool changed=false;for(size_t i=0;i<n;i++)if(memcmp(&c->route[i],&a[i].st,sizeof(Stop))!=0){changed=true;break;}
 if(changed){for(size_t i=0;i<n;i++)c->route[i]=a[i].st;s->dc_feas_version++;s->dc_car_version[ci]++;s->dc_base_valid[ci]=false;dc_prefix_invalidate(s,ci);}
 s->dc_urgent_applied_route_version[ci]=s->dc_route_version[ci];return true;
}
static bool dc_cache_prepare_group(Simulation*s,DcInfeasibleCache*cc,const uint32_t*m,size_t mn){
 if(!cc)return true;
 bool same=cc->n==mn&&cc->members&&!memcmp(cc->members,m,mn*sizeof*m);
 if(cc->car_version_n<s->cfg->car_n){uint64_t*a=es_realloc(cc->car_versions,s->cfg->car_n*sizeof*a,s->err);if(!a)return false;uint64_t*b=es_realloc(cc->urgent_car_versions,s->cfg->car_n*sizeof*b,s->err);if(!b){cc->car_versions=a;return false;}for(size_t i=cc->car_version_n;i<s->cfg->car_n;i++){a[i]=0;b[i]=0;}cc->car_versions=a;cc->urgent_car_versions=b;cc->car_version_n=s->cfg->car_n;}
 if(!same){if(cc->cap<mn){uint32_t*x=es_realloc(cc->members,mn*sizeof*x,s->err);if(!x)return false;cc->members=x;cc->cap=mn;}memcpy(cc->members,m,mn*sizeof*m);cc->n=mn;memset(cc->car_versions,0,cc->car_version_n*sizeof*cc->car_versions);memset(cc->urgent_car_versions,0,cc->car_version_n*sizeof*cc->urgent_car_versions);cc->valid=false;cc->urgent_valid=false;}
 return true;
}
static bool dc_assign_group(Simulation*s,int h,const uint32_t*m,size_t mn,bool urgent){const Passenger*seed=&s->trace.p[m[0]-1];uint32_t group_mask=dc_group_mask(s,m,mn);DcInfeasibleCache*cc=s->dc_cache?&s->dc_cache[seed->id-1]:NULL;if(!dc_cache_prepare_group(s,cc,m,mn))return false;uint64_t*cv=cc?(urgent?cc->urgent_car_versions:cc->car_versions):NULL;int best=-1;size_t best_ins=0;double bs=HUGE_VAL;Pred bp={0};int bu=0;for(size_t ci=0;ci<s->cfg->car_n;ci++){if(cv&&cv[ci]==s->dc_car_version[ci])continue;if(!(group_mask&(UINT32_C(1)<<(unsigned)ci))){if(cv)cv[ci]=s->dc_car_version[ci];continue;}size_t ins;Pred pr;double sc;if(!eta_best_for_car(s,(int)ci,h,m,mn,urgent,&ins,&pr,&sc)){if(cv)cv[ci]=s->dc_car_version[ci];continue;}int unique=0;for(size_t j=0;j<mn;j++){int d=s->trace.p[m[j]-1].dest;bool seen=false;for(size_t x=0;x<j;x++)if(s->trace.p[m[x]-1].dest==d)seen=true;if(!seen&&route_find(&s->cars[ci],d)<0)unique++;}bool take=false;if(urgent)take=best<0||(pr.pickup_s<bp.pickup_s&&!es_nearly_equal(pr.pickup_s,bp.pickup_s))||(es_nearly_equal(pr.pickup_s,bp.pickup_s)&&(int)ci<best);else{take=best<0||(sc<bs&&!es_nearly_equal(sc,bs));if(!take&&es_nearly_equal(sc,bs)){if(unique<bu)take=true;else if(unique==bu&&pr.pickup_s<bp.pickup_s&&!es_nearly_equal(pr.pickup_s,bp.pickup_s))take=true;else if(unique==bu&&es_nearly_equal(pr.pickup_s,bp.pickup_s)&&(int)ci<best)take=true;}}if(take){best=(int)ci;best_ins=ins;bs=sc;bp=pr;bu=unique;}}
if(best<0)return true;
int gid=s->next_group_id++;if(!route_insert(&s->cars[best],best_ins,(Stop){seed->origin,R_GROUP,seed->dir,gid},s->err))return false;s->dc_route_version[best]++;s->dc_base_valid[best]=false;dc_prefix_invalidate(s,best);for(size_t j=0;j<mn;j++){Passenger*p=&s->trace.p[m[j]-1];dc_unassigned_remove(s,h,p->id);p->car=best;p->group_id=gid;s->dc_pending[best]++;if(!wq_insert_id_sorted(dc_commit_q(s,best,hi(p->origin,p->dir)),p->id,s->err))return false;char q[512];ev(s,"PASSENGER_ASSIGN","passenger_id=%" PRIu32 " group_id=%d car_id=%s floor=%d destination=%d",p->id,gid,event_atom(q,sizeof q,s->cfg->cars[best].id),p->origin,p->dest);}char q[512];ev(s,"CALL_ASSIGN","kind=group car_id=%s floor=%d direction=%s",event_atom(q,sizeof q,s->cfg->cars[best].id),seed->origin,dstr(seed->dir));return true;}
static bool dc_group_urgent(const Simulation*s,const uint32_t*m,size_t n){
    uint64_t th=(uint64_t)s->cfg->starvation_s*1000000ULL;
    for(size_t i=0;i<n;i++){const Passenger*p=&s->trace.p[m[i]-1];if(p->state==P_WAITING&&s->now_us-p->arrival_us>=th)return true;}
    return false;
}
static void dc_next_epoch(Simulation*s){
    if(++s->dc_dispatch_epoch==0){memset(s->dc_seen,0,(s->trace.n?s->trace.n:1)*sizeof*s->dc_seen);s->dc_dispatch_epoch=1;}
}
static bool destination_dispatch(Simulation*s){
memset(s->dc_base_valid,0,sizeof s->dc_base_valid);dc_prefix_reset_all(s);dc_next_epoch(s);
/* Hall-level urgent event is emitted once per activation episode.  Destination
 * urgency itself is passenger/group based, so later unassigned groups at the same
 * hall are handled by the group pass below even when the hall oldest passenger
 * already belongs to another sticky group. */
for(int h=0;h<s->cfg->floors*2;h++){
    WaitQueue*q=&s->queues[h];wq_advance(q,&s->trace);if(q->head>=q->n)continue;
    Hall*hh=&s->halls[h];Passenger*old=&s->trace.p[q->ids[q->head]-1];
    if(s->now_us-old->arrival_us<(uint64_t)s->cfg->starvation_s*1000000ULL)continue;
    hh->urgent=true;
    if(!hh->urgent_logged){ev(s,"STARVATION_URGENT","floor=%d direction=%s oldest_passenger_id=%" PRIu32,hfloor(h),dstr(hdir(h)),old->id);hh->urgent_logged=true;s->starvation_triggers++;}
}
/* First partition every unassigned FIFO into candidate groups and process every
 * group containing an over-threshold passenger before any normal optimization. */
for(int h=0;h<s->cfg->floors*2;h++){
    for(uint32_t sid=s->dc_hhead[h];sid;){
        uint32_t next=s->dc_next[sid];Passenger*seed=&s->trace.p[sid-1];
        if(seed->state!=P_WAITING||seed->car>=0||(s->dc_seen&&s->dc_seen[sid-1]==s->dc_dispatch_epoch)){sid=next;continue;}
        uint32_t m[ES_MAX_CAPACITY];DcInfeasibleCache*cc=s->dc_cache?&s->dc_cache[sid-1]:NULL;size_t n=0;
        if(cc&&cc->n&&cc->members&&cc->membership_version==s->dc_hall_membership_version[h]){n=cc->n;memcpy(m,cc->members,n*sizeof*m);}else n=dc_build_group_linked(s,sid,m);dc_mark_group(s,m,n);
        if(dc_group_urgent(s,m,n)){
            bool same=cc&&cc->n==n&&cc->members&&!memcmp(cc->members,m,n*sizeof*m);
            if(!(cc&&cc->urgent_valid&&same&&cc->urgent_feas_version==s->dc_feas_version)){
                if(!dc_assign_group(s,h,m,n,true))return false;
                if(seed->car<0&&cc){if(cc->cap<n){uint32_t*x=es_realloc(cc->members,n*sizeof*x,s->err);if(!x)return false;cc->members=x;cc->cap=n;}memcpy(cc->members,m,n*sizeof*m);cc->n=n;cc->queue_n=s->dc_htail[h];cc->membership_version=s->dc_hall_membership_version[h];cc->urgent_feas_version=s->dc_feas_version;cc->urgent_valid=true;if(!same)cc->valid=false;}else if(cc)cc->urgent_valid=false;
            }
        }
        sid=next;
    }
}
/* Sticky assigned urgent groups remain on the same car.  Rebuild the stable
 * urgent prefix only when that car's committed route/urgency state requires it. */
for(size_t ci=0;ci<s->cfg->car_n;ci++)if(s->dc_urgent_applied_route_version[ci]!=s->dc_route_version[ci]){if(!dc_reorder_urgent_car(s,(int)ci))return false;}
/* Urgent assignments may remove passengers from the unassigned lists, so normal
 * optimization must repartition the remaining FIFO from a fresh epoch. */
dc_next_epoch(s);
bool dc_global_changed=s->dc_last_normal_version!=s->dc_feas_version;
if(!dc_global_changed){bool any_dirty=false;for(int h=0;h<s->cfg->floors*2;h++)if(s->dc_hall_dirty[h]){any_dirty=true;break;}if(!any_dirty)return !s->err->code;}
for(int h=0;h<s->cfg->floors*2;h++){
    if(!dc_global_changed&&!s->dc_hall_dirty[h])continue;
    for(uint32_t sid=s->dc_hhead[h];sid;){
        uint32_t next=s->dc_next[sid];Passenger*seed=&s->trace.p[sid-1];
        if(seed->state!=P_WAITING||seed->car>=0||(s->dc_seen&&s->dc_seen[sid-1]==s->dc_dispatch_epoch)){sid=next;continue;}
        uint32_t m[ES_MAX_CAPACITY];DcInfeasibleCache*cc=s->dc_cache?&s->dc_cache[sid-1]:NULL;bool extended=false;size_t n=0;
        if(cc&&cc->n&&cc->members&&cc->membership_version==s->dc_hall_membership_version[h]){n=cc->n;memcpy(m,cc->members,n*sizeof*m);extended=true;}
        else if(!dc_global_changed&&cc&&cc->valid&&cc->feas_version==s->dc_feas_version&&cc->queue_n){n=dc_extend_cached_group(s,sid,cc,(uint32_t)cc->queue_n,m,&extended);}
        if(!extended)n=dc_build_group_linked(s,sid,m);
        dc_mark_group(s,m,n);
        /* An urgent group that was infeasible in the urgent pass must never fall
         * through to the normal optimizer in the same boundary. */
        if(dc_group_urgent(s,m,n)){sid=next;continue;}
        bool same=false;if(cc&&cc->valid&&cc->n==n){same=!memcmp(cc->members,m,n*sizeof*m);}
        if(cc&&same&&cc->feas_version==s->dc_feas_version){cc->queue_n=s->dc_htail[h];sid=next;continue;}
        if(!dc_assign_group(s,h,m,n,false))return false;
        if(seed->car<0&&cc){if(cc->cap<n){uint32_t*x=es_realloc(cc->members,n*sizeof*x,s->err);if(!x)return false;cc->members=x;cc->cap=n;}memcpy(cc->members,m,n*sizeof*m);cc->n=n;cc->queue_n=s->dc_htail[h];cc->membership_version=s->dc_hall_membership_version[h];cc->feas_version=s->dc_feas_version;cc->valid=true;}else if(cc)cc->valid=false;
        sid=next;
    }
    s->dc_hall_dirty[h]=false;
}
s->dc_last_normal_version=s->dc_feas_version;
return !s->err->code;
}

static bool add_destination(Simulation*s,int ci,int floor){if(s->alg==1||s->alg==2)return route_add_sweep(s,ci,floor,R_DEST,0);return route_add_distance(s,ci,floor,R_DEST,0);}
static bool complete_transfers(Simulation*s,bool*changed){for(size_t ci=0;ci<s->cfg->car_n;ci++){CarState*c=&s->cars[ci];for(size_t i=0;i<c->alighting_n;){if(c->alighting_done[i]!=s->now_us){i++;continue;}uint32_t id=c->alighting[i];Passenger*p=&s->trace.p[id-1];p->state=P_COMPLETED;p->complete_us=s->now_us;p->has_complete=true;char q[512];ev(s,"ALIGHT_DONE","passenger_id=%" PRIu32 " car_id=%s floor=%d",id,event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);remove_u32(c->alighting,&c->alighting_n,i);size_t n=c->alighting_n+1;remove_u64(c->alighting_done,&n,i);c->alighting_n=n;*changed=true;}for(size_t i=0;i<c->boarding_n;){if(c->boarding_done[i]!=s->now_us){i++;continue;}uint32_t id=c->boarding[i];Passenger*p=&s->trace.p[id-1];p->state=P_ONBOARD;p->onboard_us=s->now_us;p->has_onboard=true;if(!car_vec_push(&c->onboard,&c->onboard_n,&c->onboard_cap,id,s->err)||!add_destination(s,(int)ci,p->dest))return false;if(s->alg==6){s->dc_feas_version++;s->dc_car_version[ci]++;s->dc_route_version[ci]++;}char q[512];ev(s,"BOARD_DONE","passenger_id=%" PRIu32 " car_id=%s floor=%d",id,event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);remove_u32(c->boarding,&c->boarding_n,i);size_t n=c->boarding_n+1;remove_u64(c->boarding_done,&n,i);c->boarding_n=n;*changed=true;}}return true;}
static void eval_motion(Simulation*s,int ci){CarState*c=&s->cars[ci];const ElevatorCfg*e=&s->cfg->cars[ci];double tau=(s->now_us-c->leg_start_us)/1e6,V=c->vpeak,x=0,v=0;if(tau<c->t_acc){x=.5*e->accel*tau*tau;v=e->accel*tau;c->motion=MOT_ACCEL;}else if(c->t_cruise>0&&tau<c->t_acc+c->t_cruise){double da=V*V/(2*e->accel);x=da+V*(tau-c->t_acc);v=V;c->motion=MOT_CRUISE;}else{double ss=tau-c->t_acc-c->t_cruise,da=V*V/(2*e->accel),cr=V*c->t_cruise;x=da+cr+V*ss-.5*e->decel*ss*ss;v=fmax(0,V-e->decel*ss);c->motion=MOT_DECEL;}if(x<0)x=0;if(x>c->leg_D)x=c->leg_D;double sign=c->leg_target>c->leg_from?1:-1;c->position=es_floor_pos(c->leg_from,s->cfg->floor_height)+sign*x;c->speed=v;}
static bool phase1(Simulation*s,bool*changed){for(size_t ci=0;ci<s->cfg->car_n;ci++){CarState*c=&s->cars[ci];if(c->moving&&c->leg_arrival_us==s->now_us){c->moving=false;c->floor=c->leg_target;c->position=es_floor_pos(c->floor,s->cfg->floor_height);c->speed=0;c->motion=MOT_STOPPED;c->dir=DIR_IDLE;char q[512];ev(s,"CAR_ARRIVE","car_id=%s floor=%d",event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);if(c->has_current_stop&&c->current_stop.reasons==R_STAGE){c->staging_arrivals++;c->has_current_stop=false;}*changed=true;}else if(c->moving)eval_motion(s,(int)ci);if((c->door==DOOR_OPENING||c->door==DOOR_CLOSING)&&c->timer_end_us==s->now_us){char q[512];if(c->door==DOOR_OPENING){c->door=DOOR_OPEN;c->open_since_us=s->now_us;ev(s,"DOOR_OPEN","car_id=%s floor=%d",event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);}else{c->door=DOOR_CLOSED;ev(s,"DOOR_CLOSED","car_id=%s floor=%d",event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);c->has_current_stop=false;}*changed=true;}}return complete_transfers(s,changed);}
static bool inject(Simulation*s){while(s->next_arrival<s->trace.n&&s->trace.p[s->next_arrival].arrival_us==s->now_us){Passenger*p=&s->trace.p[s->next_arrival++];p->state=P_WAITING;p->queue_us=s->now_us;int h=hi(p->origin,p->dir);if(!wq_push(&s->queues[h],p->id,s->err))return false;if(s->alg==6){dc_unassigned_append(s,h,p->id);s->dc_hall_dirty[h]=true;}char qs[1024];ev(s,"PASSENGER_ARRIVE","passenger_id=%" PRIu32 " origin=%d destination=%d segment=%s",p->id,p->origin,p->dest,event_atom(qs,sizeof qs,p->segment));}return true;}
static bool start_alight(Simulation*s,bool*changed){for(size_t ci=0;ci<s->cfg->car_n;ci++){CarState*c=&s->cars[ci];if(c->door!=DOOR_OPEN)continue;size_t free=(size_t)s->cfg->cars[ci].alight_lanes-c->alighting_n;while(free){size_t bi=SIZE_MAX;uint32_t bid=UINT32_MAX;for(size_t i=0;i<c->onboard_n;i++){Passenger*p=&s->trace.p[c->onboard[i]-1];if(p->dest==c->floor&&p->id<bid){bid=p->id;bi=i;}}if(bi==SIZE_MAX)break;Passenger*p=&s->trace.p[bid-1];p->state=P_ALIGHTING;p->alight_start_us=s->now_us;p->has_alight=true;if(c->reserved)c->reserved--;s->dc_feas_version++;s->dc_car_version[ci]++;remove_u32(c->onboard,&c->onboard_n,bi);uint64_t done=s->now_us+qus(s->cfg,s->cfg->cars[ci].alight_ms);if(!lane_push(c,false,bid,done,s->err))return false;char q[512];ev(s,"ALIGHT_START","passenger_id=%" PRIu32 " car_id=%s floor=%d",bid,event_atom(q,sizeof q,s->cfg->cars[ci].id),c->floor);free--;*changed=true;}}return true;}
static bool start_board(Simulation*s,bool*changed){for(size_t ci=0;ci<s->cfg->car_n;ci++){CarState*c=&s->cars[ci];if(c->door!=DOOR_OPEN)continue;size_t free=(size_t)s->cfg->cars[ci].board_lanes-c->boarding_n;for(int dp=0;dp<2&&free;dp++){int dir=dp==0?1:-1;WaitQueue*q=&s->queues[hi(c->floor,dir)];wq_advance(q,&s->trace);for(size_t k=q->head;k<q->n&&free&&c->reserved<(uint32_t)s->cfg->cars[ci].capacity;k++){Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state!=P_WAITING||!car_serves_od(&s->cfg->cars[ci],p->origin,p->dest)||!policy_board_ok(s,(int)ci,p))continue;p->state=P_BOARDING;if(s->alg==6&&p->car==(int)ci){if(s->dc_pending[ci])s->dc_pending[ci]--;wq_advance(dc_commit_q(s,(int)ci,hi(p->origin,p->dir)),&s->trace);s->dc_route_version[ci]++;}p->car=(int)ci;p->board_start_us=s->now_us;p->has_board_start=true;c->reserved++;if(c->reserved>c->max_reserved)c->max_reserved=c->reserved;uint64_t done=s->now_us+qus(s->cfg,s->cfg->cars[ci].board_ms);if(!lane_push(c,true,p->id,done,s->err))return false;char qq[512];ev(s,"BOARD_START","passenger_id=%" PRIu32 " car_id=%s floor=%d",p->id,event_atom(qq,sizeof qq,s->cfg->cars[ci].id),c->floor);free--;*changed=true;}}
if(c->reserved>=(uint32_t)s->cfg->cars[ci].capacity&&c->has_current_stop&&(c->current_stop.reasons&R_BYPASS_MARK)==0){for(int d=-1;d<=1;d+=2){WaitQueue*q=&s->queues[hi(c->floor,d)];for(size_t k=q->head;k<q->n;k++){Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state==P_WAITING&&car_serves_od(&s->cfg->cars[ci],p->origin,p->dest)&&policy_board_ok(s,(int)ci,p)){p->bypassed++;c->full_bypass++;ev_full_bypass(s,p->id,s->cfg->cars[ci].id,c->floor);}}}c->current_stop.reasons|=R_BYPASS_MARK;}}
return !s->err->code;}
static bool immediately_boardable(const Simulation*s,int ci){const CarState*c=&s->cars[ci];if(c->reserved>=(uint32_t)s->cfg->cars[ci].capacity)return false;for(int d=-1;d<=1;d+=2){const WaitQueue*q=&s->queues[hi(c->floor,d)];for(size_t k=q->head;k<q->n;k++){const Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state==P_WAITING&&car_serves_od(&s->cfg->cars[ci],p->origin,p->dest)&&policy_board_ok(s,ci,p))return true;}}return false;}
static bool need_service_here(const Simulation*s,int ci,const Stop*st){if(st->reasons&R_DEST)return true;if(st->reasons&R_GROUP)for(int d=-1;d<=1;d+=2){const WaitQueue*q=&s->queues[hi(st->floor,d)];for(size_t k=q->head;k<q->n;k++){const Passenger*p=&s->trace.p[q->ids[k]-1];if(p->state==P_WAITING&&p->car==ci&&p->group_id>=0)return true;}}if(st->reasons&R_HALL_UP){Hall*h=&s->halls[hi(st->floor,1)];if(h->active&&h->owner==ci)return true;}if(st->reasons&R_HALL_DOWN){Hall*h=&s->halls[hi(st->floor,-1)];if(h->active&&h->owner==ci)return true;}return false;}
